post.description:
POST /api/v1/abac/check
Body: {
  resourceType: string,
  action: string,
  resourceId?: string,
  environment?: { ip?: string, userAgent?: string, ... }
}

Returns: { allowed: boolean, reason: string, matchedPolicies: [...] }

POST /api/v1/abac/check-bulk
Body: {
  checks: [
    { resourceType: string, action: string, resourceId?: string },
    ...
  ],
  environment?: { ... }
}

